// Module 8 evidence: installs one real appliance from a package generated by the dev stack, lets it enroll
// with the dev agent gateway and report health, then captures the fleet page, the deployment's health and
// logs pages, the health policy page, and the appliance's own status; it also stops the appliance's
// database to show the dashboard turning critical from real reports. Removes the appliance afterwards.
// Requires the dev API to listen on the host address (AGENT_GATEWAY_HOST=0.0.0.0). Usage: node scripts/screenshots-m8.mjs
import { spawnSync } from 'node:child_process';
import { randomBytes } from 'node:crypto';
import { mkdirSync, mkdtempSync, readFileSync, realpathSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from '@playwright/test';

const base = process.env.BASE_URL ?? 'http://localhost:3210';
const outDir = fileURLToPath(new URL('../../../docs/reports/module-08/', import.meta.url));
const shots = `${outDir}screenshots/`;
mkdirSync(shots, { recursive: true });
const env = Object.fromEntries(readFileSync(new URL('../../api/.env', import.meta.url), 'utf8').split(/\r?\n/).filter((l) => /^[A-Z0-9_]+=/.test(l)).map((l) => [l.slice(0, l.indexOf('=')), l.slice(l.indexOf('=') + 1)]));
const sh = (cmd, timeout = 400_000) => {
  const r = spawnSync('wsl', ['--exec', 'bash', '-c', cmd], { encoding: 'utf8', timeout });
  return { code: r.status, out: (r.stdout ?? '').trim(), err: (r.stderr ?? '').trim() };
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const browser = await chromium.launch({ channel: 'msedge' });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2 });
const page = await ctx.newPage();
const login = await page.request.post(`${base}/api/v1/auth/login`, { data: { email: 'avery.admin@psacc.test', password: env.SEED_DEFAULT_PASSWORD }, headers: { origin: base } });
if (login.status() !== 200) throw new Error(`login ${login.status()}`);
const csrf = async () => ({ origin: base, 'x-csrf-token': (await ctx.cookies()).find((c) => c.name === 'psacc_csrf').value });
const api = async (method, path, data) => {
  const r = await page.request.fetch(`${base}/api/v1${path}`, { method, data, headers: await csrf() });
  if (!r.ok()) throw new Error(`${method} ${path} → ${r.status()} ${await r.text()}`);
  return (r.headers()['content-type'] ?? '').includes('json') ? r.json() : r.body();
};
const shot = async (p, name, full = true) => {
  await p.evaluate(() => window.scrollTo(0, 0));
  await p.addStyleTag({ content: 'nextjs-portal { display: none !important; }' }).catch(() => undefined);
  await p.waitForTimeout(400);
  await p.screenshot({ path: `${shots}${name}.png`, fullPage: full });
  console.log('saved', name);
};

const inst = (await api('GET', '/psa-instances?provider=connectwise&status=active&pageSize=50')).items.find((i) => i.client.code !== 'CL-00001' && i.enabledServiceCount > 0);
const dep = await api('POST', '/deployments', { clientId: inst.client.id, psaInstanceId: inst.id, targetEnvironment: 'local_test', targetOs: 'linux', targetArch: 'amd64', hostLabel: 'module8-demo' });
const pkg = (await api('POST', `/deployments/${dep.id}/packages`, { tokenValidityHours: 4 })).currentPackage;
const zip = await api('POST', `/deployments/${dep.id}/packages/${pkg.id}/download`);
const winTmp = realpathSync.native(mkdtempSync(join(tmpdir(), 'psacc-m8-')));
writeFileSync(join(winTmp, pkg.fileName), zip);
const project = `psacc-${dep.code.toLowerCase()}`;
const work = `/tmp/psacc-m8shots/${project}`;
const port = 18000 + (Number(dep.code.replace(/\D/g, '')) % 1000);
const unixZip = sh(`wslpath -a '${join(winTmp, pkg.fileName)}'`).out;

try {
  let r = sh(`rm -rf /tmp/psacc-m8shots && mkdir -p /tmp/psacc-m8shots && cd /tmp/psacc-m8shots && unzip -q "${unixZip}" && cd ${project} && cp config/edge.env.template .env && echo EDGE_BACKUP_INITIAL_DELAY_SECONDS=3 >> .env && scripts/install.sh`);
  if (r.code !== 0) throw new Error(`install failed: ${r.err || r.out}`);
  let d;
  for (let n = 0; n < 60; n++) {
    d = await api('GET', `/deployments/${dep.id}`);
    if (d.lifecycleState === 'verified') break;
    await sleep(2000);
  }
  if (d.lifecycleState !== 'verified') throw new Error(`deployment is ${d.lifecycleState}/${d.healthState}, not verified`);
  await sleep(35_000); // a few more report cycles for the resource chart

  await page.goto(`${base}/monitoring`, { waitUntil: 'networkidle' });
  await shot(page, '01-fleet-health');
  await page.goto(`${base}/monitoring?live=1`, { waitUntil: 'networkidle' });
  await shot(page, '02-fleet-live-only', false);
  await page.goto(`${base}/deployments/${dep.id}/health`, { waitUntil: 'networkidle' });
  await shot(page, '03-deployment-health-healthy');
  await page.goto(`${base}/deployments/${dep.id}`, { waitUntil: 'networkidle' });
  await shot(page, '04-deployment-overview-verified', false);
  await page.goto(`${base}/settings/health`, { waitUntil: 'networkidle' });
  await shot(page, '05-health-policy');

  const local = `http://127.0.0.1:${port}`;
  const ui = await ctx.newPage();
  await ui.goto(`${local}/`);
  const password = `demo-${randomBytes(9).toString('base64url')}`;
  await ui.fill('#username', 'localadmin');
  await ui.fill('#password', password);
  await ui.fill('#confirm', password);
  await ui.click('button[type=submit]');
  await ui.waitForURL(/\/credentials/);
  await ui.goto(`${local}/`);
  await shot(ui, '06-appliance-status', false);

  // Real degradation: stop the appliance database and wait for the dashboard to evaluate it critical.
  sh(`cd ${work} && docker compose -f compose.yaml stop edge-postgres`, 120_000);
  for (let n = 0; n < 60; n++) {
    d = await api('GET', `/deployments/${dep.id}`);
    if (d.healthState === 'critical') break;
    await sleep(2000);
  }
  await page.goto(`${base}/deployments/${dep.id}/health`, { waitUntil: 'networkidle' });
  await shot(page, '07-deployment-health-critical-db-stopped');
  sh(`cd ${work} && docker compose -f compose.yaml start edge-postgres`, 120_000);
  for (let n = 0; n < 60; n++) {
    d = await api('GET', `/deployments/${dep.id}`);
    if (d.healthState === 'healthy') break;
    await sleep(2000);
  }
  await page.goto(`${base}/deployments/${dep.id}/logs`, { waitUntil: 'networkidle' });
  await shot(page, '08-deployment-logs-after-recovery');
  const h = await api('GET', `/deployments/${dep.id}/health`);
  writeFileSync(`${outDir}health-api-sample.json`, JSON.stringify({ healthState: h.healthState, healthReason: h.healthReason, findings: h.findings, events: h.events, latestTypes: Object.keys(h.latest), hostResources: h.latest.host_resources?.payload, containers: h.latest.containers?.payload, database: { ...h.latest.database?.payload, tables: `${h.latest.database?.payload.tables.length} tables (inventory omitted)` } }, null, 2));
  r = sh(`cd ${work} && docker compose -f compose.yaml logs --no-log-prefix edge-agent | grep -E 'enrolled|reports delivered|started' | head -6`);
  writeFileSync(`${outDir}agent-log-excerpt.txt`, `$ docker compose logs edge-agent\n${r.out}\n`);
} finally {
  sh(`cd ${work} && docker compose -f compose.yaml down --volumes --remove-orphans; rm -rf /tmp/psacc-m8shots`);
  rmSync(winTmp, { recursive: true, force: true });
  await browser.close();
}
